WITH store_agg AS (SELECT sr_customer_sk, SUM(sr_net_loss) AS store_net_loss, COUNT(*) AS store_return_cnt FROM store_returns GROUP BY sr_customer_sk), web_agg AS (SELECT wr_refunded_customer_sk AS customer_sk, SUM(wr_net_loss) AS web_net_loss, COUNT(*) AS web_return_cnt FROM web_returns GROUP BY wr_refunded_customer_sk), cust_demo AS (SELECT c.c_customer_sk, c.c_customer_id, c.c_first_name, c.c_last_name, c.c_birth_year, cd.cd_gender, cd.cd_marital_status, cd.cd_education_status FROM customer c LEFT JOIN customer_demographics cd ON c.c_current_cdemo_sk = cd.cd_demo_sk) SELECT cd.c_customer_id, cd.c_first_name, cd.c_last_name, cd.c_birth_year, cd.cd_gender, cd.cd_marital_status, cd.cd_education_status, COALESCE(sa.store_net_loss, 0) + COALESCE(wa.web_net_loss, 0) AS total_net_loss, COALESCE(sa.store_return_cnt, 0) + COALESCE(wa.web_return_cnt, 0) AS total_return_cnt, CASE WHEN COALESCE(sa.store_net_loss, 0) + COALESCE(wa.web_net_loss, 0) > 10000 THEN 'HIGH' WHEN COALESCE(sa.store_net_loss, 0) + COALESCE(wa.web_net_loss, 0) BETWEEN 5000 AND 10000 THEN 'MEDIUM' ELSE 'LOW' END AS loss_category, RANK() OVER (ORDER BY COALESCE(sa.store_net_loss, 0) + COALESCE(wa.web_net_loss, 0) DESC) AS loss_rank FROM cust_demo cd LEFT JOIN store_agg sa ON cd.c_customer_sk = sa.sr_customer_sk LEFT JOIN web_agg wa ON cd.c_customer_sk = wa.customer_sk WHERE COALESCE(sa.store_net_loss, 0) + COALESCE(wa.web_net_loss, 0) > 0 ORDER BY total_net_loss DESC LIMIT 100
